using System;using System.IO;using System.Linq;using System.Text.RegularExpressions;using System.Collections.Generic;using System.Globalization;
namespace V15Voice {
public sealed class TextTargetResult {
 public double Target,Minimum,Maximum,Adjustment;public double? Natural,Required,Speed,Measured;public bool Fitted,Complete;public string Reason="",Wav="";
 public readonly List<VoiceReportAttempt> Attempts=new List<VoiceReportAttempt>();
 public string Describe(){return "TXT đích "+Scripts.Stamp(Target)+" · gốc "+(Natural.HasValue?Scripts.Stamp(Natural.Value):"chưa đo")+" · tốc độ "+(Speed.HasValue?Speed.Value.ToString("0.000",CultureInfo.InvariantCulture)+"x":"chưa căn")+" · "+(Complete?"WAV đã xuất":Fitted?"đã căn, chưa xuất WAV":Reason.Length>0?Reason:"đang đo/căn");}
}
public static class TextTargetVoice {
 public static double Parse(string value,bool allowBlank=false){string s=(value??"").Trim();if(s.Length==0&&allowBlank)return 0;s=Regex.Replace(s,@"\s*(?:s|giây)$","",RegexOptions.IgnoreCase).Trim().Replace(',','.');double seconds;
  if(Regex.IsMatch(s,@"^\d+(?:\.\d{1,3})?$")){if(!Double.TryParse(s,NumberStyles.AllowDecimalPoint,CultureInfo.InvariantCulture,out seconds))throw new Exception("Thời lượng đích không hợp lệ.");}
  else{var m=Regex.Match(s,@"^(?:(\d{1,2}):)?(\d{1,3}):(\d{2}(?:\.\d{1,3})?)$");if(!m.Success)throw new Exception("Nhập giây, mm:ss hoặc hh:mm:ss, ví dụ 45 / 01:30 / 00:01:30.");double sec=Double.Parse(m.Groups[3].Value,CultureInfo.InvariantCulture);int minutes=Int32.Parse(m.Groups[2].Value);if(sec>=60||(m.Groups[1].Success&&minutes>=60))throw new Exception("Phút/giây trong timecode không hợp lệ.");seconds=(m.Groups[1].Success?Int32.Parse(m.Groups[1].Value)*3600:0)+minutes*60+sec;}
  ValidateSeconds(seconds);return seconds;
 }
 public static void ValidateSeconds(double seconds){if(Double.IsNaN(seconds)||Double.IsInfinity(seconds)||seconds<1||seconds>Scripts.MaxSeconds)throw new Exception("Thời lượng đích phải từ 1 giây đến 6 giờ.");}
 public static double Minimum(RenderOptions o){return Math.Max(Tempo.Minimum(o),o.BaseSpeed*(1-o.TargetChange));}
 public static double Maximum(RenderOptions o){return Math.Min(Tempo.Maximum(o),o.BaseSpeed*(1+o.TargetChange));}
 public static void Validate(RenderOptions o){ValidateSeconds(o.TargetSeconds);if(!o.Prose||o.Anchored||o.Locked)throw new Exception("Thời lượng đích riêng chỉ dùng cho TXT tự nhiên; SRT dùng timeline nguồn.");Tempo.Validate(o);if(Double.IsNaN(o.TargetChange)||Double.IsInfinity(o.TargetChange)||o.TargetChange<.01||o.TargetChange>.25)throw new Exception("Giới hạn căn TXT phải trong ±1% đến ±25%.");}
 static double TailSilence(string path){using(var b=new BinaryReader(File.OpenRead(path))){b.BaseStream.Position=12;while(b.BaseStream.Position+8<=b.BaseStream.Length){string id=new string(b.ReadChars(4));uint size=b.ReadUInt32();long at=b.BaseStream.Position;if(id=="data"){int n=(int)Math.Min(2400,size/2);b.BaseStream.Position=at+size-n*2;var a=new short[n];for(int i=0;i<n;i++)a[i]=b.ReadInt16();int silent=0;for(int i=n-1;i>=0&&Math.Abs((int)a[i])<45;i--)silent++;return silent/24000.0;}b.BaseStream.Position=at+size+size%2;}}return 0;}
 static int Timeout(double seconds){return (int)Math.Min(3600000,Math.Max(120000,seconds*3000));}
 public static string Render(List<Cue> cues,KokoroEngine engine,RenderOptions o,string output,Action<int,string> progress){Validate(o);var r=new TextTargetResult{Target=o.TargetSeconds,Minimum=Minimum(o),Maximum=Maximum(o)};o.TargetResult=r;
  string parent=Path.GetDirectoryName(Path.GetFullPath(output));if(!Directory.Exists(parent))throw new DirectoryNotFoundException(parent);string work=Path.Combine(parent,".v15_txt_target_"+Guid.NewGuid().ToString("N"));bool normalize=o.NormalizeLoudness;var reading=o.ReadingChanged;
  try{Directory.CreateDirectory(work);o.NormalizeLoudness=false;o.ReadingChanged=reading==null?(Action<ReadingProgress>)null:p=>{p.Final=false;p.Stage="TXT gốc trước căn đích · "+p.Stage;reading(p);};string original;
   try{original=Renderer.RenderNatural(cues,engine,o,Path.Combine(work,"natural.wav"),(p,m)=>progress(p*70/100,"Đo TXT gốc · "+m));}finally{o.NormalizeLoudness=normalize;o.ReadingChanged=reading;}
   long sourceFrames=FinalAudio.PcmFrames(original),targetFrames=(long)Math.Round(r.Target*24000);r.Natural=sourceFrames/24000.0;r.Required=o.BaseSpeed*r.Natural.Value/r.Target;double selected=Math.Max(r.Minimum,Math.Min(r.Maximum,r.Required.Value));string candidate=Path.Combine(work,"candidate.wav");
   if(o.RunReport!=null)o.RunReport.Step("FIT","Căn toàn bộ TXT theo thời lượng đích");
   for(int attempt=0;attempt<8;attempt++){if(engine.Cancelled)throw new OperationCanceledException();double factor=selected/o.BaseSpeed;progress(72+attempt*2,"Căn TXT đích · thử "+(attempt+1)+" · "+selected.ToString("0.000",CultureInfo.InvariantCulture)+"x");if(File.Exists(candidate))File.Delete(candidate);
    if(Math.Abs(factor-1)<.00001)File.Copy(original,candidate);else AudioProcess.Run(engine.Root,"-v error -y -i "+KokoroEngine.Q(original)+" -af atempo="+factor.ToString("0.000000",CultureInfo.InvariantCulture)+" -ac 1 -ar 24000 -c:a pcm_s16le "+KokoroEngine.Q(candidate),()=>engine.Cancelled,Timeout(r.Natural.Value));
    long measured=FinalAudio.PcmFrames(candidate),delta=targetFrames-measured;r.Measured=measured/24000.0;r.Speed=selected;var trial=new VoiceReportAttempt{Speed=selected,Measured=r.Measured.Value,Target=r.Target,Note="Đã đo PCM sau căn toàn bộ TXT; luôn xử lý từ audio gốc"};r.Attempts.Add(trial);if(o.RunReport!=null)o.RunReport.TargetAttempt(trial);
    bool safe=delta>=0||TailSilence(candidate)>=-delta/24000.0+.003;if(Math.Abs(delta)<=480&&safe){r.Adjustment=delta/24000.0;r.Fitted=true;break;}double correction=delta<0&&Math.Abs(delta)<=480&&!safe?.005:0,next=Math.Max(r.Minimum,Math.Min(r.Maximum,selected*(r.Measured.Value+correction)/r.Target));if(Math.Abs(next-selected)<.000001)break;selected=next;
   }
   if(!r.Fitted){double difference=r.Measured.Value-r.Target;r.Reason=(difference<0?"Thiếu ":"Dư ")+Math.Abs(difference).ToString("0.000",CultureInfo.InvariantCulture)+" giây sau căn trong giới hạn "+r.Minimum.ToString("0.000",CultureInfo.InvariantCulture)+"–"+r.Maximum.ToString("0.000",CultureInfo.InvariantCulture)+"x. "+(difference<0?"Cần bổ sung nội dung phù hợp hoặc giảm thời lượng đích.":"Cần rút gọn lời hoặc tăng thời lượng đích.")+" Chưa xuất WAV; không tự chèn im lặng dài hoặc cắt lời.";if(o.RunReport!=null)o.RunReport.Step("FIT_RESULT","TXT không vừa thời lượng đích trong giới hạn");throw new Exception(r.Reason);}
   string exact=Path.Combine(work,"exact.wav");if(o.RunReport!=null)o.RunReport.Step("ASSEMBLE","Bù sai số đuôi TXT tối đa 20 ms, giữ nguyên lời");if(r.Adjustment==0)File.Copy(candidate,exact);else AudioProcess.Run(engine.Root,"-v error -y -i "+KokoroEngine.Q(candidate)+" -af apad=whole_len="+targetFrames+",atrim=end_sample="+targetFrames+" -ac 1 -ar 24000 -c:a pcm_s16le "+KokoroEngine.Q(exact),()=>engine.Cancelled,Timeout(r.Target));
   if(o.RunReport!=null)o.RunReport.Step("FORMAT","Kiểm tra số mẫu TXT đích");if(FinalAudio.PcmFrames(exact)!=targetFrames)throw new IOException("WAV TXT không khớp thời lượng đích.");
   if(normalize){if(o.RunReport!=null)o.RunReport.Step("NORMALIZE","Cân âm lượng WAV TXT đích");string norm=Path.Combine(work,"normalized.wav");FinalAudio.Normalize(engine.Root,exact,norm,targetFrames,o.TargetLufs,()=>engine.Cancelled,engine.ReportActivity);exact=norm;}
   if(engine.Cancelled)throw new OperationCanceledException();if(o.RunReport!=null)o.RunReport.Step("PUBLISH","Lưu WAV TXT đích cạnh nguồn");r.Wav=OutputFiles.Publish(exact,output);r.Complete=true;foreach(var c in cues)c.Status="TXT đích · căn chung "+r.Speed.Value.ToString("0.000",CultureInfo.InvariantCulture)+"x; mốc trước căn";if(o.RunReport!=null)o.RunReport.TargetDone(r.Speed.Value);
   if(reading!=null)reading(new ReadingProgress{Done=cues.Count,Total=cues.Count,Words=cues.Sum(c=>c.Words),AudioSeconds=r.Target,Final=true,Stage=r.Describe()+" · bảng giữ mốc TRƯỚC căn; chưa đo mốc từng câu sau căn"});progress(100,r.Describe());return r.Wav;
  }catch(Exception e){if(r.Reason.Length==0)r.Reason=e.Message;throw;}finally{o.NormalizeLoudness=normalize;o.ReadingChanged=reading;try{Directory.Delete(work,true);}catch{}}
 }
}
}
